__NUXT_JSONP__("/ar/going-to-college", (function(a,b,c,d,e){return {data:[{details:{slug:d,pageTitle:"MLI شركاء في الجامعات و الكليات | Mentor Language Institute",pageDescription:e,title:"MLI شركاء في الجامعات و الكليات",university:{title:"اتفاقيات الجامعة",description:e,lists:[{image:"\u002Fimages\u002Fgoing-to-college\u002Fyum.png",link:"https:\u002F\u002Fwww.adelphi.edu\u002F",title:"Adelphi University",address:"Long Island, New York",subtitle:c,description:"Adelphi University يعزز في طلابه شغفا بالمعرفه والفهم والتساؤل حول القيم الثقافية ورؤية لانفسهم كمتعلمين ومستقلين طوال حياتهم ومساهمين في المعرفة والخدمة في عالم دائم التغير"},{image:"\u002Fimages\u002Fgoing-to-college\u002Finternational-accelerator.png",link:"https:\u002F\u002Fwww.american.edu\u002F",title:"American University",address:"Washington, D.C.",subtitle:c,description:"International Accelerator يقدم البرنامج مجموعة واسعه ومرنة من التخصصات لمختلف المستويات. يمكن للطلاب دراسة تخصصين, أو دراسة تخصص ثاني بالاضافة للتخصص الرئيسي الذي درسة,يمكن للطالب الالتحاق بجامعتنا ك جامعة اضافية بالاضافة لجامعته الرئيسية . International Accelerator يشجع الطلاب توسيع دائرته الثقافية بتعدد التخصصات."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fauburn-university.png",link:"https:\u002F\u002Fwww.auburn.edu\u002F",title:"Auburn University",address:"Auburn, Alabama",subtitle:c,description:"تسعى جامعة أبرون إلى تهيئة الطلاب للاقتضاد العالمي في الوقت الحالي, مكتب الطلاب الدوليين يقدم المعلومات اللازمة للطلاب عن الهجرة وخيارات الدراسة في الخارج والعديد من المعلومات, كما يقدم معلومات عن المبادرات التي ترعاها الوحدات الأكاديمي, و القبول الجامعي لطلاب البكالوريوس و الدراسات العليا."},{image:"\u002Fimages\u002Fgoing-to-college\u002Ffloria-international-university.png",link:"https:\u002F\u002Fwww.fiu.edu\u002F",title:"Floria International University",address:"Miami, Florida",subtitle:a,description:"ترحب منظمة Florida International بالطلاب في مجتمع متنوع وودي, حيث تساعد الاتصالات الصناعية وفرص التدريب في اطلاق حياتهم المهنية في سوق عالمية. في Flu سوف يتلقون تعليم متميز في مدينة ريادة الاعمال."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flouisiana-state-university.png",link:"https:\u002F\u002Fwww.lsu.edu\u002F",title:"Louisiana State University",address:"Baton Rougue, Louisiana",subtitle:a,description:"الحصول على درجة Louisiana State University هو استثمار في مستقبل الطالب. تقدم Louisiana State University تعليما استثنائيا وفرصا للحصول على خبره جامعيه ممتازة و برسوم دراسية جيدة."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-kansas.png",link:"https:\u002F\u002Fwww.ku.edu\u002F",title:"The University of Kansas",address:"Lawrence, Kansas",subtitle:a,description:"مجموعة من المنح الدراسية المتقدمة والاختراع والاكتشاف , يوفر جامعة KU التعليم الذي يسهم في بناء قادة العالم , والرواد في العديد من المجالات  المختلفة, وكما انه يسهم في اثراء خبرات الطلاب الجامعية التي من سوفل تعود بأثر ايجابي وتغير حياتهم."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-central-florida.png",link:"https:\u002F\u002Fwww.ucf.edu\u002F",title:"University of Central Florida",address:"Orlando, Florida",subtitle:a,description:"الطلاب لديهم احلام كبيره.ربما يريدون السفر حول العالم او ادارة اعمالهم الخاصه او الاحتفاظ براءات الاختراع التي تساعد في انقاذ الارواح. سوف تساعدهم جامعة Central Florida في تحقيق أحلامهم"},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-the-pacific.png",link:"https:\u002F\u002Fwww.pacific.edu\u002F",title:"University of the Pacific",address:"Stockton, California",subtitle:a,description:"تقع الجامعه الدولية Pacific في حرم جامعي جميل على بعد 1.5 ساعه من سان فرانسيسكو. تقدم الجامعة مختلف التخصص منها التالي: الفنون الليبرالية,الهندسة والاعمال ,وكذلك تقدم برامج للدراسات العليا في طب الاسنان ,والقانون , والصيدلة, والعلوم الصحية. تعتبر الجامعه الدولية Pacific اقدم جامعة مستاجره في ولاية كاليفورنيا, كما أنها أول جامعة قدمت قبول للطالبات."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-south-carolina.png",link:"https:\u002F\u002Fwww.sc.edu\u002F",title:"University of South Carolina",address:"Columbia, South Carolina",subtitle:a,description:"جامعة South Carolina هي المكان الذي يستعيد فيه الطلاب ليكونوا حل المشكلات في المستقبل , واللذين سيقودون الاجيال القادمة الى اسلوب حياة اكثر صحة وذكاء واكثر حيوية."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-illinois.png",link:"https:\u002F\u002Fwww.uic.edu\u002F",title:"University of Illinois at Chicago",address:"Chicago, Illinois",subtitle:a,description:"توسع جامعة University of llinois في شيكاغو الفرص التعليمية للطلاب من جميع انحاء العالم من خلال التركيز على التنوع وتزويد الطلاب ببيئة تعلم ثرية ثقافيا."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-utah.png",link:"https:\u002F\u002Fwww.utah.edu\u002F",title:"The University of Utah",address:"Salt Lake City, Utah",subtitle:a,description:"تعتبر جامعة ولاية Utah واحده من افضل الجامعات في البلاد في انشاء الشركات الناشئة على اساس ابحاث الطلاب والهيئات التدريسية. وهذا يدل على التفكير المبتكر والجهود المبذولة من كادر الجامعة لمساعدة الطلاب على تحقيق طموحاتهم."},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-dayton.png",link:"https:\u002F\u002Fwww.udayton.edu\u002F",title:"University of Dayton",address:"Dayton, Ohio",subtitle:a,description:"تتميز الجامعة بالفلسفة التعليمية لتعلم المجتمع, و الترحيب بالجميع, و خدمة الآخرين, كما أنها تحفز التفكير الناقد لتعزيز القادة الذين يربطون التعليم مع الخدمة و القيادة."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fumass-amherst.png",link:"https:\u002F\u002Fwww.umass.edu\u002F",title:"UMass Amherst",address:"Amherst, Massachusetts",subtitle:a,description:"UMass Amherst هي واحده من اكبر جامعات الابحاث العامة في امريكا. يتم تصنيف الحرم الجامعي في Amherst, Massachusetts , وهو من افضل الجامعات العامة للابحاث في البلاد , ويوفر بيئة ثقافية غنية في بيئة. ريفية قريبه من المراكز الحضرية الرئيسية"},{image:"\u002Fimages\u002Fgoing-to-college\u002Funiversity-of-cincinnati.png",link:"https:\u002F\u002Fwww.uc.edu\u002F",title:"University of Cincinnati",address:"Cincinnati, Ohio",subtitle:a,description:"مع Cincinnati موطن لخمسة عشر الف شركة, فان جامعة Cincinnati هي مركز للمستقبل , وقادة, والذين لديهم عطش للمعرفة. في المرتبة رقم 135 في الجامعات الوطنية وفقا لتقرير الولايات المتحدة والاخبار العالمية, فانه يفتخر بتخريج عدد كبير من الطلاب من جميع انحاء العالم."}]},campus:{title:"College Agreements",description:"لدى MLI اتفاقيات خاصة, او كليات منطقة Mutual Angeles. تتيح برامج التعرف على (MRP) هذه , مع العديد من خانات Los للطلاب نقل نقاط TOEFL والبعض الاخر يسمح بالتسجيل المتزامن, مما يعني ان طلاب MLI يستطيعون الحصول على درجات الائتمان بدوام جزئي بينما لا يزالون مسجلين في MLI. يجب على الطلاب ان يستكملوا برنامج MLI عالي المستوى ليكونوا مؤهلين.",lists:[{image:"\u002Fimages\u002Fgoing-to-college\u002Fsanta-monica-college.png",link:"https:\u002F\u002Fwww.smc.edu\u002F",title:"Santa Monica College",address:"Santa Monica, California",subtitle:a,description:"على مدار 27 عام على التوالي ساهمت كلية سانتامونيكا في تحويل الطلاب إلى العديد من الجامعات في كاليفورنيا ومنها جامعة UCLA, USC ,وكذلك جامعة Loyola Marymount. وكذلك أيضا في ولاية Mississippi الى جامعة Ivy league Columbia"},{image:"\u002Fimages\u002Fgoing-to-college\u002Fglendale-community-college.png",link:"https:\u002F\u002Fwww.glendale.edu\u002F",title:"Glendale Community College",address:"Glendale, California",subtitle:a,description:"تعد كلية Glendale مؤسسة ديناميكية تضم اكثر من 25000 طالبا. يتم تسجيل ساعاتهم الدراسية في الحرم الجامعي erdugo, كما أنهم يتلقون التعليم المستمر في حرم غارفيلد, وفصول الخدمات المجتمعية التي تخدم المجتمع, ومركز التطوير المهني (PDC) الموجود في Montrose. تخدم الكلية هيئة طلابية متنوعة بشكل كبير, ولا توجد مجموعة واحده تشكل الاغلبية"},{image:"\u002Fimages\u002Fgoing-to-college\u002Fpasadena-city-college.png",link:"https:\u002F\u002Fpasadena.edu\u002F",title:"Pasadena City College",address:"Pasadena, California",subtitle:a,description:"توفر كلية Pasadena بيئة تعليمية عالية الجودة ومبتكره وديناميكية تلهم نجاح الطلاب. في كل فصل دراسي تقدم برامج اكاديمية تشمل الدرجات العلمية, ومعادلة الساعات للطلاب الذين يرغبون التحويل, والشهادات الى اكثر من 30,250 طالبا. نحن نرحب بالجميع بم في ذلك الطلاب جدد والطلاب عائدين. و الطلاب المحليين, من يرغبون التعليم عن بعد عن طريق الانترنت. كليتنا ترحب  العديد من الثقافات -LGBT, متعددةالثقافات,وقدامى المحاربين, و جميع المتهمين."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fcypress-college.png",link:"https:\u002F\u002Fwww.cypresscollege.edu\u002F",title:"Cypress College",address:"Cypress, California",subtitle:a,description:"تؤكد كلية Cypress على تعليم للطالب الفردي, يمنح امتياز التعليم ومختبرات التعليم الفردية امكانية تحقيق الطلاب لاعلى امكانتهم, بالاضافه الى ذلك, يقدم فريق من المدرسين والمستشارين المتفرغين الدعم التعليمي ومعلومات توجيهية مكثفة لمساعدة الطلاب في اختيارهم للبرامج والدروس. بالنسبه للطلاب الذين يخططون لاكمال درجة البكالوريوس, توفر الكلية انتقالا سلسا من المدرسة الى الكليات والجامعات."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fwest-los-angeles-college.png",link:"http:\u002F\u002Fwww.wlac.edu\u002F",title:"West Los Angeles College",address:"Culver City, California",subtitle:a,description:"كلية West Los Angeles هي كلية معتمده من كاليفورنيا تساهم في مساعدة الطلاب للتحويل إلى الجامعة , والتعليم المهني كما تسعى للتنمية الشخصية او المهنية. مع وجود عدد طلاب نشط من 12,000 طالب في المرحلة التحضيرية والارشاد, يعمل لدينا 110 من اعضاء هيئة التدريس المتفرغين, واكثر من 300 موظف في كل ساعة و 112 موظفا متخصصا في انشاء بيئة تعليمية فريدة في جنوب كاليفورنيا."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fel-camino-college.png",link:"https:\u002F\u002Fwww.elcamino.edu\u002F",title:"El Camino College",address:"Torrance, California",subtitle:a,description:"هل تعلم ان كلية El Camino تقدم العديد من الميزاتت الرائعة؟\u003Cul\u003E\u003Cli\u003Eمؤسسة رائدة بجنوب كالليفورنيا \u003C\u002Fli\u003E\u003Cli\u003Eفي موقع ملائم ومتسع لوقوف السيارات \u003C\u002Fli\u003E\u003Cli\u003Eبرامج تعليم المجتمع المتميز\u003C\u002Fli\u003E\u003Cli\u003Eاكثر من 80 برنامج مهني موصى به.\u003C\u002Fli\u003E\u003C\u002Ful\u003E"},{image:"\u002Fimages\u002Fgoing-to-college\u002Fpierce-college.png",link:"http:\u002F\u002Fwww.piercecollege.edu\u002F",title:"Pierce College",address:b,subtitle:a,description:"كلية Pierce هي مؤسسة مزدهرة لمدة عامين في جنوب كاليفورنيا توفر فرصا لنقل التعليم والتدريب المهني والتعلم مدى الحياة, وتجمع بين التميز الاكاديمي مع هيئة التدريس والموظفين اللطيفين والذين يقدمون مساعدتهم المستمرة للطلاب. يتمتع المعهد بسمعة قوية كونه مؤسسة ملائمة للطلاب, حيث يقدم للطلاب تعليما عالي الجودة ومليء بالتحديات من شأنه إعداد التعليم الجامعي او المهني. يستفيد الطلاب Pierce من صغر أحجام الفصول الدراسة وكذلك إنخفتض الرسوم الدراسية مقارنة بالجامعة ذات الأربع سنوات."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flatcc.png",link:"http:\u002F\u002Fwww.lattc.edu\u002F",title:"LATCC - Traning. Transfer. Tradition. Trade Tech.",address:b,subtitle:a,description:"هدفنا هو: أن الكلية التجارة التقنية في لوس انجلوس تقدم المجتمعات من خلال المسارات الى النجاح الاكاديمي والمهني, ونقل النجاح لتقوية الطلاب من أجل الحصول على الشهادات الفنية المهنية, والدرجات الجامعية , والنقل, والتوظيف. رؤيتنا: ستصبح كلية لوس انجلوس التقنية التجارية كاكبر مجتمع محلي معترف به اقليميا ووطنيا لتحويل حياة الطلاب ومجتمعاتهم."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flos-angeles-harbor-college.png",link:"https:\u002F\u002Fwww.lahc.edu\u002F",title:"Los Angeles Harbor College",address:b,subtitle:a,description:"تعمل كلية Los Angeles Harbor على تعزيز نجاح الطالب من خلال درجات الزمالة , والشهادات , والتطوير الاقتصادي وتنمية القوى العاملة , وتعليم المهارات الاساسية. تلبي برامجنا التعليمية وخدمات الدعم تحقق احتياجات المجتمعات المتنوعة وفقا لحصائل التعليم المؤسسي في الحرم الجامعي."},{image:"\u002Fimages\u002Fgoing-to-college\u002Fnew-york-film-academy.png",link:"https:\u002F\u002Fwww.nyfa.edu\u002F",title:"New York Film Academy",address:"Battery Place, New York",subtitle:a,description:"على مدى السنوات 25 الماضية , قامت New York Film Academy ببناء سمعة كالمدرسة الرائده في الفنون المرئية وفنون الاداء في العالم. تم تصميم برامجنا المبتكرة لجيل جديد من رواة القصص للفنانين الذين يشتركون في شغف الفنون البصرية والمسرحية , عبر مجموعة واسعة من وسائل الاعلام ويرغبون في التعليم من خلال العمل. من خلال منهج منقطع النظير للتعليم العملي , يجد الطلاب انفسهم شغفهم في مجرى دراستهم منذ اليوم الاول. حيق يتم تدريس الفصول الدراسية من قبل المتخصصين في الصناعة الحائزين على جوائز , في بيئة اقتصادية حقيقية مزوده باحداث معدات المرافق."},{image:"\u002Fimages\u002Fgoing-to-college\u002Flacc-city-college.png",link:"https:\u002Fwww.lacitycollege.edu",title:"Los Angeles City College",address:b,subtitle:a,description:"يوفر LACC بيئة تعليمية ديناميكية ومبتكرة تقدم أكثر من 100 برنامج مهني ومهني بما في ذلك الدرجات وبرامج التحويل والشهادات لأكثر من 18000 طالب. في عام 2019 ، ستحتفل LACC بالذكرى التسعين لتأسيسها.\u003Cbr\u003Eبموجب وعد LA College ، نقدم عامًا واحدًا من التسجيل المجاني لجميع الطلاب بدوام كامل المتخرجين من المدارس الثانوية والمدارس المستقلة في LAUSD. نحن نقدم أيضًا دروسًا في مجال الموسيقى ، وحضورًا مجانيًا ، ودروسًا خاصة ومساعدة مالية بفضل هدية من The Herb Alpert Foundation. بالإضافة إلى ذلك ، يستفيد طلابنا من مجموعة متنوعة من خيارات المساعدة المالية."}]},contactUs:{title:"لمعلومات اكثر تواصل معنا.",description:"للتواصل عن طريق الهاتف او البريد الاكتروني او عبر قنوات التواصل الاجتماعي الخاصة بنا.",btnText:"Contact Us"},dir:"\u002Fgoing-to-college",path:"\u002Fgoing-to-college\u002Far",extension:".json",createdAt:"2026-10-22T16:31:29.392Z",updatedAt:"2025-05-26T12:06:27.769Z"},lang:d}],fetch:{},mutations:void 0}}("","Los Angeles, California","(Graduate Programs Available)","ar","الطلاب اللذين انتهوا من Mentor Language Institute's يمكنك التقديم على بكالوريوس و ماجستير بدون اي من اختبار التوفل او الايلتس عند الانتهاء من امتحان الجامعه المعتمد وتلبية مؤهلاتهم الاكاديمية")));